def tonelli_shanks(i, n):
    if pow(i, (n-1)//2, n) == 1:
        return int(mod(i, n).sqrt())
    return -1 

def find(i, lv):
    if lv <= 4:
        x = tonelli_shanks(i, n)
        if(x != -1):
            print(long_to_bytes(x), lv)
            find(x, lv+1)

        x = (-x) % n
        if(x != -1):
            print(long_to_bytes(x), lv)
            find(x, lv+1)

find(ct, 0)
